"""Prefix reconstruction: turning a decision oracle into a shortest-program finder."""

from itertools import product
from typing import Callable, List, Optional, Tuple

Str = Tuple[int, ...]
DecisionOracle = Callable[[Str, Str, int], bool]


def all_strings(length: int) -> List[Str]:
    return [tuple(bits) for bits in product((0, 1), repeat=length)]


def rebuild(dec: Callable[[Str, int], bool], n: int, w: Str = ()) -> Str:
    """Descend the prefix tree, always taking a branch that keeps a solution alive.

    `dec(w, m)` must answer "is there p of length m with D(w + p) = y?" for the
    fixed target y. Exactly n queries are made, one per output bit.
    """
    while n > 0:
        w = w + ((0,) if dec(w + (0,), n - 1) else (1,))
        n -= 1
    return w


def decision_to_finder(dec: DecisionOracle, fuel: int, y: Str) -> Optional[Str]:
    """Least feasible length by bounded search, then bit-by-bit reconstruction.

    Cost: at most fuel + 1 queries for the length search, then exactly K(y)
    queries for the reconstruction. Correct whenever `dec` answers correctly
    about the single target y -- its answers about other strings are irrelevant.
    """
    for n in range(fuel + 1):
        if dec(y, (), n):
            return rebuild(lambda w, m: dec(y, w, m), n)
    return None


def ideal_oracle(decoder: Callable[[Str], Str]) -> DecisionOracle:
    """The brute-force prefix-decision oracle: correct, but not efficient."""
    def dec(y: Str, w: Str, n: int) -> bool:
        return any(decoder(w + p) == y for p in all_strings(n))
    return dec


def locally_correct_oracle(decoder: Callable[[Str], Str], target: Str,
                           garbage: Callable[[Str, int], bool]) -> DecisionOracle:
    """Correct at `target`, arbitrary garbage everywhere else."""
    ideal = ideal_oracle(decoder)

    def dec(y: Str, w: Str, n: int) -> bool:
        return ideal(y, w, n) if y == target else garbage(w, n)
    return dec


if __name__ == "__main__":
    def toy(p: Str) -> Str:
        if not p:
            return ()
        return p[1:] if p[0] == 0 else p[1:] + p[1:]

    target: Str = (1, 0, 1, 0)
    ideal = ideal_oracle(toy)
    local = locally_correct_oracle(toy, target, lambda w, n: (len(w) + n) % 2 == 0)

    a = decision_to_finder(ideal, 5, target)
    b = decision_to_finder(local, 5, target)
    print("ideal            ->", a, "decodes to", toy(a) if a else None)
    print("locally correct  ->", b, "identical:", a == b)
